package main
import("bufio";"strings";"testing";"net";"time")
func TestCompatible(t *testing.T){for _,p:=range []string{
"HTTP/enhanced 200 OK\r\n", "HTTP/enhanced 200 Ok\r\n", "HTTP/1.1 200 OK\r\n", "HTTP/1.0 200 Connection established\r\nX-Test: yes\r\n\r\n", "\r\nHTTP/enhanced 200 OK\r\n\r\n", "GET-RAY / HTTP/1.1\r\nHost: test\r\n\r\n", "BMOVE / HTTP/1.1\r\nHost: test\r\n\r\n", "PATCH / HTTP/1.1\r\nHost: test\r\n\r\n]"}{br:=bufio.NewReader(strings.NewReader(p+"SSH-2.0-test\r\n"));if e:=discardPreamble(br);e!=nil{t.Errorf("%q: %v",p,e)}else{v,_:=br.Peek(4);if string(v)!="SSH-"{t.Fatal("lost SSH bytes")}}}}
func TestRejected(t *testing.T){for _,p:=range []string{"HTTP/1.1 garbage\r\n", "HTTP/enhanced 999 OK\r\n", "HTTP/1.1 200 OK\r\nContent-Length: 9\r\n\r\n", "HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\n\r\n", "PATCH / HTTP/1.1\r\nContent-Length: 9\r\n\r\n", "]]",strings.Repeat("\r\n",33),"GET / HTTP/1.1\r\nX-Test: "+strings.Repeat("a",maxPreambleBytes)+"\r\n\r\n"}{if e:=discardPreamble(bufio.NewReader(strings.NewReader(p+"SSH-2.0-test\r\n")));e==nil{t.Errorf("invalid preamble accepted")}}}
func TestSplit(t *testing.T){a,b:=net.Pipe();defer a.Close();defer b.Close();a.SetReadDeadline(time.Now().Add(time.Second));go func(){for _,v:=range []string{"HTTP/en","hanced 200 OK\r\n","PATCH / HTTP/1.1\r\nHost: test\r\n\r\n","SSH-2.0-test\r\n"}{b.Write([]byte(v));time.Sleep(10*time.Millisecond)}}();if e:=discardPreamble(bufio.NewReader(a));e!=nil{t.Fatal(e)}}
